insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i024$il$, $il$MediaMarkt Saturn policy URL does not load$il$, $il$Data & schema$il$, $il$Both$il$, $il$nice$il$, $il$open$il$, $il$Oliver$il$, '2026-09-09T08:12:00.000Z'::timestamptz, 5, '{}'::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$C119 MediaMarkt Saturn. The Policy URL field holds two links and neither loads. Refresh them, and add a periodic link check across Policy URL and Source URLs that flags dead ones for re-research rather than letting them quietly decay.$il$,
$il$Why it matters beyond one link: the policy URL is the evidence behind the IPID test, which is what decides greenfield versus incumbent. A dead link means the verdict can no longer be checked. MediaMarkt is a real incumbent, Zurich Gruppe Deutschland on an exclusive partnership to at least 2035, with claims through AQILO, so the verdict itself is not in doubt here. The general problem is link rot across the evidence fields.

Worth a periodic link check on Policy URL and Source URLs, flagging dead ones for re-research rather than letting them quietly decay.$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i025$il$, $il$Comments or instructions field on company and lead, routable to the research agent$il$, $il$Research agent$il$, $il$Brad$il$, $il$must$il$, $il$open$il$, $il$Oliver$il$, '2026-09-09T08:13:00.000Z'::timestamptz, 3, array[$il$i003$il$,$il$i040$il$]::text[], array[$il$i001$il$]::text[], null, null, false, false, $il${"Oliver": "2026-09-15T13:06:56.870Z"}$il$::jsonb,
$il$A free text field on a company or a contact where Oliver writes what he has noticed or wants checked. Two routes out of it: someone applies it by hand, or it is queued for the research agent. Where it is queued, the agent writes its answer back underneath rather than overwriting the note. The note carries who wrote it, when, and a status of raw, actioned or queued.$il$,
$il$NOTE ON PRIORITY: Oliver raised this alongside two low priority items but I have put it in Must have, so knock it back if you disagree. The reason is that this is the correction loop, and right now there is not one. On 4 September Oliver walked eight checkouts and two of them overturned a confident desk verdict, both in the optimistic direction: DiTech.at had a Wertgarantie policy the research had missed, and BA-Computer could not be shown to sell a device at all. Those corrections only survived because he typed them into a Claude session that happened to be open. Without a field like this, the single highest quality input to the data has nowhere to go.

Suggested shape: the note carries who wrote it and when, a status of raw, actioned or queued for research, and where it was queued the agent writes its answer back underneath rather than overwriting the note.$il$);

